function w(u,i,o,e){let n=e;if(!u){const l=e.length;n=new Array(l);for(let t=0;t<l;++t)n[t]=e[t]}n[i]=o;return n}function f(u,i,o){const e=o.length-1;let n=0;let l=0;let t=o;if(u){n=l=i}else{t=new Array(e);while(n<i)t[l++]=o[n++]}++n;while(n<=e)t[l++]=o[n++];if(u){t.length=e}return t}function g(u,i,o,e){const n=e.length;if(u){let h=n;while(h>=i)e[h--]=e[h];e[i]=o;return e}let l=0,t=0;const c=new Array(n+1);while(l<i)c[t++]=e[l++];c[i]=o;while(l<n)c[++t]=e[l++];return c}export{g as arraySpliceIn,f as arraySpliceOut,w as arrayUpdate};
